// Extra bindings that are not generated by Wrangler. Optional so the
// Cloudflare Worker build keeps working without them.
interface CloudflareBindings {
  /** Raw database handle for Better Auth (Node `DatabaseSync`). Falls back to DB. */
  AUTH_DB?: unknown
  /** Extra origins allowed to call the API (comma separated). */
  TRUSTED_ORIGINS?: string
  /** Set to "production" to enable secure cookies and strict checks. */
  APP_ENV?: string
  VAPID_PUBLIC_KEY?: string
  VAPID_PRIVATE_KEY?: string
  VAPID_SUBJECT?: string
}

/** Delivers one Web Push message. Provided by the Node server only. */
type PushSender = (
  subscription: { endpoint: string; p256dh: string; auth: string },
  payload: string,
) => Promise<{ ok: true } | { ok: false; gone: boolean }>

interface CloudflareBindings {
  PUSH_SENDER?: PushSender
}
